// data/*.yaml -> src/data.generated.js, so the Worker does not parse YAML at runtime.
import { readFileSync, writeFileSync } from "node:fs";
import { parse } from "yaml";

const root = new URL("../", import.meta.url);
const holidays = parse(readFileSync(new URL("data/holidays.yaml", root), "utf8"));
const { questions } = parse(readFileSync(new URL("data/questions.yaml", root), "utf8"));

const out =
  "// Generated by scripts/build-data.mjs from data/*.yaml. Do not edit.\n" +
  `export const HOLIDAYS = ${JSON.stringify(holidays)};\n` +
  `export const QUESTIONS = ${JSON.stringify(questions)};\n`;
writeFileSync(new URL("src/data.generated.js", root), out);
